-- Monetization: topic packs (one-time Play unlocks), power-ups charged on the
-- server (coins or tokens), rewarded ads verified by AdMob server-side
-- verification, and Quiz Pass perks.
--
-- Logging rule: every movement of value (coins, gems, power-up tokens) is a
-- wallet_ledger row written in the same database transaction as the balance
-- change. Every ad reward, from request to payout, is one ad_rewards row.

-- 1. Topic packs are non-consumable Play products that unlock subjects. -------

-- Drop the two checks that mention kind (names were generated by 000009).
DO $$
DECLARE c record;
BEGIN
    FOR c IN SELECT conname FROM pg_constraint
              WHERE conrelid = 'billing_products'::regclass AND contype = 'c'
                AND pg_get_constraintdef(oid) LIKE '%kind%'
    LOOP
        EXECUTE format('ALTER TABLE billing_products DROP CONSTRAINT %I', c.conname);
    END LOOP;
END $$;

ALTER TABLE billing_products
    ADD CONSTRAINT billing_products_kind_check
        CHECK (kind IN ('consumable', 'subscription', 'non_consumable')),
    -- A pack gives currency; a subscription or topic pack gives access, not currency.
    ADD CONSTRAINT billing_products_grant_check
        CHECK ((kind = 'consumable' AND coins + gems > 0)
            OR (kind IN ('subscription', 'non_consumable') AND coins = 0 AND gems = 0));

-- Which subjects a topic pack unlocks. A subject listed here is locked for a
-- player until they own one of its packs. Subjects in no pack stay free.
CREATE TABLE billing_product_subjects (
    product_id varchar(64) NOT NULL REFERENCES billing_products (product_id) ON DELETE CASCADE,
    subject    varchar(32) NOT NULL REFERENCES subjects (code) ON DELETE CASCADE,
    PRIMARY KEY (product_id, subject)
);

-- "Which packs unlock this subject?" (the primary key covers the reverse).
CREATE INDEX idx_billing_product_subjects_subject ON billing_product_subjects (subject);

-- "Which products does this player own?" (topic packs are granted purchases).
CREATE INDEX idx_play_purchases_client_product ON play_purchases (client_id, product_id) WHERE state = 'granted';

-- 2. One ledger for every asset. ------------------------------------------------
-- Power-up tokens are logged in wallet_ledger exactly like coins and gems.

DO $$
DECLARE c record;
BEGIN
    FOR c IN SELECT conname FROM pg_constraint
              WHERE conrelid = 'wallet_ledger'::regclass AND contype = 'c'
                AND pg_get_constraintdef(oid) LIKE '%currency%'
    LOOP
        EXECUTE format('ALTER TABLE wallet_ledger DROP CONSTRAINT %I', c.conname);
    END LOOP;
END $$;

ALTER TABLE wallet_ledger ADD CONSTRAINT wallet_ledger_currency_check
    CHECK (currency IN ('coins', 'gems', 'experience', 'fifty_fifty', 'add_time', 'skip'));

-- Daily caps and per-type history for one player.
CREATE INDEX idx_wallet_ledger_client_type_created ON wallet_ledger (client_id, transaction_type, created_at DESC);
-- Reports across players: one transaction type over a time window.
CREATE INDEX idx_wallet_ledger_type_created ON wallet_ledger (transaction_type, created_at DESC);
-- Server-issued rewards and charges carry a unique reference, so writing the
-- same event twice fails instead of paying (or charging) twice.
CREATE UNIQUE INDEX uq_wallet_ledger_server_event
    ON wallet_ledger (client_id, transaction_type, currency, reference_id)
    WHERE transaction_type IN ('ad_reward', 'pass_reward', 'power_up_charge', 'power_up_token_use')
      AND reference_id IS NOT NULL;

-- 3. Power-ups. -------------------------------------------------------------------

-- Tokens a player holds (earned from rewarded ads or the Quiz Pass) and can
-- spend instead of coins. Every change is also a wallet_ledger row.
CREATE TABLE client_power_ups (
    client_id  integer NOT NULL REFERENCES clients (id) ON DELETE CASCADE,
    power_up   varchar(20) NOT NULL CHECK (power_up IN ('fifty_fifty', 'add_time', 'skip')),
    quantity   integer NOT NULL DEFAULT 0 CHECK (quantity >= 0 AND quantity <= 99),
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (client_id, power_up)
);

-- One row per power-up used in a game. The primary key makes a use (and its
-- charge) happen once, however often the request is retried. question_code is
-- '*' for power-ups allowed once per run (Sudden Death +5s and Skip).
CREATE TABLE power_up_uses (
    session_id    varchar(64) NOT NULL,
    question_code varchar(64) NOT NULL,
    power_up      varchar(20) NOT NULL CHECK (power_up IN ('fifty_fifty', 'add_time', 'skip')),
    client_id     integer NOT NULL REFERENCES clients (id) ON DELETE CASCADE,
    paid_with     varchar(10) NOT NULL CHECK (paid_with IN ('coins', 'gems', 'token')),
    amount        integer NOT NULL CHECK (amount > 0),
    result        varchar(64) NOT NULL DEFAULT '',   -- e.g. the options 50:50 hid ("b,d")
    created_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (session_id, question_code, power_up)
);

CREATE INDEX idx_power_up_uses_client_created ON power_up_uses (client_id, created_at DESC);

-- 4. Rewarded ads: one table for every ad reward. ----------------------------------
-- A row is created when the player asks to watch an ad (the server checks the
-- daily caps then), carries Google's signed server-side verification callback
-- (transaction id, ad unit, key) and records exactly what was paid. Quiz Pass
-- holders get the same rewards without an ad (source = 'pass', no callback).
CREATE TABLE ad_rewards (
    id                 uuid PRIMARY KEY,                 -- random (v4); sent to AdMob as custom_data
    client_id          integer NOT NULL REFERENCES clients (id) ON DELETE CASCADE,
    placement          varchar(32) NOT NULL CHECK (placement IN ('ad_chest', 'fifty_fifty', 'add_time', 'skip')),
    source             varchar(10) NOT NULL DEFAULT 'ad' CHECK (source IN ('ad', 'pass')),
    status             varchar(12) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'fulfilled', 'expired')),
    reward_currency    varchar(20) CHECK (reward_currency IN ('coins', 'gems', 'fifty_fifty', 'add_time', 'skip')),
    reward_amount      integer CHECK (reward_amount > 0),
    ad_network         varchar(40),
    ad_unit            varchar(100),
    ssv_transaction_id varchar(128),
    ssv_key_id         bigint,
    ssv_rewarded_at    timestamptz,                      -- AdMob's timestamp for the reward
    created_at         timestamptz NOT NULL DEFAULT now(),
    expires_at         timestamptz NOT NULL,
    fulfilled_at       timestamptz,
    -- A fulfilled reward always says what it paid, and an ad reward always has
    -- Google's verified transaction behind it.
    CHECK (status <> 'fulfilled' OR (reward_currency IS NOT NULL AND reward_amount IS NOT NULL AND fulfilled_at IS NOT NULL)),
    CHECK (source <> 'ad' OR status <> 'fulfilled' OR ssv_transaction_id IS NOT NULL)
);

-- Google sends each reward once per transaction id; a replayed callback cannot pay again.
CREATE UNIQUE INDEX uq_ad_rewards_ssv_transaction ON ad_rewards (ssv_transaction_id) WHERE ssv_transaction_id IS NOT NULL;
-- Daily caps and history: one player's rewards by time, and by placement.
CREATE INDEX idx_ad_rewards_client_created ON ad_rewards (client_id, created_at DESC);
CREATE INDEX idx_ad_rewards_client_placement_created ON ad_rewards (client_id, placement, created_at DESC);
-- The sweeper expires pending requests nobody finished.
CREATE INDEX idx_ad_rewards_pending_expires ON ad_rewards (expires_at) WHERE status = 'pending';
-- Reports: rewards paid per day and placement.
CREATE INDEX idx_ad_rewards_fulfilled ON ad_rewards (fulfilled_at, placement) WHERE status = 'fulfilled';
